package genheader_test

import (
	"testing"

	"github.com/cristianargotti/golaw/internal/genheader"
)

func TestConventionReadsTheHeaderBeforeThePackageClauseOnly(t *testing.T) {
	t.Parallel()
	tests := map[string]struct {
		content string
		want    bool
	}{
		"red: the golaw header on the first line":    {"// Code generated by golaw 0.3.0 kind=port@1; DO NOT EDIT.\n\npackage ledgertest\n", true},
		"red: the sqlc header and its version lines": {"// Code generated by sqlc. DO NOT EDIT.\n// versions:\n//   sqlc v1.31.1\n\npackage sqlcgen\n", true},
		"red: after a build line and a package doc":  {"//go:build go1.22\n\n// Package apigen provides primitives.\n//\n// Code generated by github.com/oapi-codegen/oapi-codegen/v2 version v2.8.0 DO NOT EDIT.\npackage apigen\n", true},
		"red: CRLF line endings":                     {"// Code generated by sqlc. DO NOT EDIT.\r\npackage sqlcgen\r\n", true},
		"near: quoted in the body":                   {"package growth\n\nconst header = `\n// Code generated by golaw 0.3.0 kind=port@1; DO NOT EDIT.\n`\n", false},
		"near: after the package clause":             {"package x\n// Code generated by x. DO NOT EDIT.\n", false},
		"near: inside a block comment":               {"/*\n// Code generated by x. DO NOT EDIT.\n*/\npackage x\n", false},
		"near: without the final period":             {"// Code generated by x. DO NOT EDIT\npackage x\n", false},
		"near: indented":                             {"  // Code generated by x. DO NOT EDIT.\npackage x\n", false},
		"near: empty":                                {"", false},
	}
	for name, tc := range tests {
		t.Run(name, func(t *testing.T) {
			t.Parallel()
			if got := genheader.Convention([]byte(tc.content)); got != tc.want {
				t.Errorf("Convention = %v, want %v", got, tc.want)
			}
		})
	}
}
